 /// <summary>
/// This class is used to update the stopped settings of InventItem*Setup
/// depending on the item state.
/// </summary>
public class AVAAVASCMItemStateUpdateV2 extends RunBase
{
    str                     dummy;

    InventTable             inventTable;
    KCS_KAOItemStateTable   itemStateTable;
    boolean                 showProgress;

    Map                     siteSettings;

    #define.currentVersion(1)
    #localmacro.currentList
        dummy
    #endmacro

}

Method.Source:
/// <summary>
/// Add our controls to the dialog.
/// </summary>
/// <returns>
/// The updated dialog object.
/// </returns>
public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.addText("@NDX:NXAItemStateUpdate");

    return dialog;
}

/// <summary>
/// Calculate how many records are affected by the update.
/// </summary>
/// <returns>
/// Number of affected records.
/// </returns>
private int64 getAffectedRecordCount()
{
    InventItemInventSetup   inventItemInventSetup;
    InventItemPurchSetup    inventItemPurchSetup;
    InventItemSalesSetup    inventItemSalesSetup;
    InventTable             localInventTable;

    if (inventTable)
    {
        select count(RecId) from inventItemInventSetup
            where inventItemInventSetup.ItemId == inventTable.ItemId;

        select count(RecId) from inventItemPurchSetup
            where inventItemPurchSetup.ItemId == inventTable.ItemId;

        select count(RecId) from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == inventTable.ItemId;
    }
    else
    {
        select count(RecId) from inventItemInventSetup
            exists join localInventTable
            where localInventTable.ItemId == inventItemInventSetup.ItemId
                && localInventTable.KCS_KAOItemState == itemStateTable.ItemState;

        select count(RecId) from inventItemPurchSetup
            exists join localInventTable
            where localInventTable.ItemId == inventItemPurchSetup.ItemId
                && localInventTable.KCS_KAOItemState == itemStateTable.ItemState;

        select count(RecId) from inventItemSalesSetup
            exists join localInventTable
            where localInventTable.ItemId == inventItemSalesSetup.ItemId
                && localInventTable.KCS_KAOItemState == itemStateTable.ItemState;
    }

    return inventItemInventSetup.RecId + inventItemPurchSetup.RecId + inventItemSalesSetup.RecId;
}

/// <summary>
/// Retrieve the setting for a specific site.
/// </summary>
/// <param name="_inventSiteId">
/// Site for which to retrieve setup.
/// </param>
/// <returns>
/// The setting for the passed site.
/// </returns>
private KCS_KAOItemStateSiteSetup getSiteSetting(InventSiteId _inventSiteId)
{
    if (siteSettings.exists(_inventSiteId))
    {
        return siteSettings.lookup(_inventSiteId);
    }

    return null;
}

/// <summary>
/// Load site specific settings and store them in a map for later usage.
/// </summary>
private void loadSiteSettings()
{
    KCS_KAOItemStateSiteSetup itemStateSiteSetup;

    siteSettings = new Map(Types::String, Types::Record);

    while select itemStateSiteSetup
        where itemStateSiteSetup.ItemState == itemStateTable.ItemState
    {
        siteSettings.insert(itemStateSiteSetup.InventSiteId, itemStateSiteSetup.data());
    }
}

/// <summary>
/// Initializes a new instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </summary>
protected void new()
{
    super();
}

/// <summary>
/// Serializes the current instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </summary>
/// <returns>
/// A container that contains the current instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// Gets or sets the <c>InventTable</c> parameter.
/// </summary>
/// <param name="_inventTable">
/// The value to set.
/// </param>
/// <returns>
/// The value of the <c>InventTable</c> parameter.
/// </returns>
public InventTable parmInventTable(InventTable _inventTable = inventTable)
{
    inventTable = _inventTable;
    return inventTable;
}

/// <summary>
/// Gets or sets the <c>ItemStateTable</c> parameter.
/// </summary>
/// <param name="_itemStateTable">
/// The value to set.
/// </param>
/// <returns>
/// The value of the <c>ItemStateTable</c> parameter.
/// </returns>
public KCS_KAOItemStateTable parmItemStateTable(KCS_KAOItemStateTable _itemStateTable = itemStateTable)
{
    itemStateTable = _itemStateTable;
    return itemStateTable;
}

/// <summary>
/// Gets or sets the <c>ShowProgress</c> parameter.
/// </summary>
/// <param name="_showProgress">
/// The value to set.
/// </param>
/// <returns>
/// The value of the <c>ShowProgress</c> parameter.
/// </returns>
public boolean parmShowProgress(boolean _showProgress = showProgress)
{
    showProgress = _showProgress;
    return showProgress;
}

/// <summary>
/// Execute the update.
/// </summary>
public void run()
{
    #OccRetryCount
    #AviFiles
    InventItemInventSetup       inventItemInventSetup;
    InventItemPurchSetup        inventItemPurchSetup;
    InventItemSalesSetup        inventItemSalesSetup;
    InventTable                 localInventTable;
    InventDim                   inventDim;
    KCS_KAOItemStateSiteSetup   itemStateSiteSetup;
    SysOperationProgress        sysOperationProgress;


    if (showProgress)
    {
        sysOperationProgress = SysOperationProgress::newGeneral(#AviUpdate,
                                                                    AVAAVASCMItemStateUpdateV2::description(),
                                                                    this.getAffectedRecordCount());
    }

    if (inventTable)
    {
        itemStateTable = KCS_KAOItemStateTable::find(inventTable.KCS_KAOItemState);
    }

    this.loadSiteSettings();

    try
    {

        while select ItemId, RecId from localInventTable
            where (inventTable.ItemId && localInventTable.ItemId == inventTable.ItemId)
                || (!inventTable.ItemId && localInventTable.KCS_KAOItemState == itemStateTable.ItemState)
        {
            if (showProgress)
            {
                sysOperationProgress.setText(strfmt("@SYS14077", localInventTable.ItemId));
            }

            while select forupdate inventItemInventSetup
                where inventItemInventSetup.ItemId == localInventTable.ItemId
            {

                inventDim = inventItemInventSetup.inventDim();
                itemStateSiteSetup = this.getSiteSetting(inventDim.InventSiteId);
                if (itemStateSiteSetup && inventDim.InventSiteId)                    
                {
                    if (inventItemInventSetup.Override)
                    {                           
                        inventItemInventSetup.avaSCMInitFromItemStateMap(itemStateSiteSetup);                            
                    }
                }
                else
                {
                    inventItemInventSetup.avaSCMInitFromItemStateMap(itemStateTable); 
                }

                ttsbegin;
                inventItemInventSetup.update();
                ttscommit;

                if (showProgress)
                {
                    sysOperationProgress.incCount();
                }
            }

            while select forupdate inventItemPurchSetup
                where inventItemPurchSetup.ItemId == localInventTable.ItemId
            {
                inventDim = inventItemPurchSetup.inventDim();
                itemStateSiteSetup = this.getSiteSetting(inventDim.InventSiteId);
                if (itemStateSiteSetup && inventDim.InventSiteId)                    
                {
                    if (inventItemPurchSetup.Override)
                    {                           
                        inventItemPurchSetup.avaSCMInitFromItemStateMap(itemStateSiteSetup);                            
                    }
                }
                else
                {
                    inventItemPurchSetup.avaSCMInitFromItemStateMap(itemStateTable); 
                }

                ttsbegin;
                inventItemPurchSetup.update();
                ttscommit;

                if (showProgress)
                {
                    sysOperationProgress.incCount();
                }
            }

            while select forupdate inventItemSalesSetup
                where inventItemSalesSetup.ItemId == localInventTable.ItemId
            {                    
                inventDim = inventItemSalesSetup.inventDim();
                itemStateSiteSetup = this.getSiteSetting(inventDim.InventSiteId);
                if (itemStateSiteSetup && inventDim.InventSiteId)                   
                {
                    if (inventItemSalesSetup.Override)
                    {                           
                        inventItemSalesSetup.avaSCMInitFromItemStateMap(itemStateSiteSetup);                           
                    }
                }
                else
                {
                    inventItemSalesSetup.avaSCMInitFromItemStateMap(itemStateTable); 
                }

                ttsbegin;
                inventItemSalesSetup.update();
                ttscommit;

                if (showProgress)
                {
                    sysOperationProgress.incCount();
                }
            }
        }

    }
    catch (exception::DeadLock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() < #RetryNum)
        {
            retry;
        }
        else
        {
            throw Exception::UpdateConflictNotRecovered;
        }
    }


}

/// <summary>
/// Deserializes the
/// <paramref name="_packedClass"/>
///  parameter value to an instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </summary>
/// <param name="_packedClass">
/// The container from which to deserialize the instance.
/// </param>
/// <returns>
/// true if deserialization was successful; otherwise, false.
/// </returns>
public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;
        default:
            return false;
    }

    return true;
}

/// <summary>
/// Initializes a new instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </summary>
/// <returns>
/// A new instance of the <c>AVAUPPItemStateUpdate</c> class.
/// </returns>
public static AVAAVASCMItemStateUpdateV2 construct()
{
    return new AVAAVASCMItemStateUpdateV2();
}

/// <summary>
/// Gets the description of the class.
/// </summary>
/// <returns>
/// The description of the class.
/// </returns>
public static ClassDescription description()
{
    return "@NDX:NXAItemStateUpdate";
}

/// <summary>
/// Run update for a single InventTable record, e.g. when the item state assigned
/// has been changed by the user.
/// </summary>
/// <param name="_inventTable">
/// InventTable record for which the flags have to be updated.
/// </param>
public static server void runInventTable(InventTable _inventTable)
{
    AVAAVASCMItemStateUpdateV2 itemStateUpdate = AVAAVASCMItemStateUpdateV2::construct();

    itemStateUpdate.parmInventTable(_inventTable);
    itemStateUpdate.runOperation();
}

/// <summary>
/// Update all InventTable records which have the passed item state assigned, e.g. when
/// the setup of the item state has been changed by the user.
/// </summary>
/// <param name="_itemStateTable">
/// Item state table with the setup of what to block.
/// </param>
/// <param name="_prompt">
/// Specify whether the user shall be prompted to confirm the update or not.
/// </param>
public static server void runItemState(KCS_KAOItemStateTable _itemStateTable, boolean _prompt)
{
    AVAAVASCMItemStateUpdateV2 itemStateUpdate = AVAAVASCMItemStateUpdateV2::construct();

    itemStateUpdate.parmItemStateTable(_itemStateTable);
    itemStateUpdate.parmShowProgress(false);

    if (!_prompt || itemStateUpdate.prompt())
    {
        itemStateUpdate.runOperation();
    }
}

/// <summary>
/// canRunInNewSession
/// </summary>
/// <returns> boolean value </returns>
protected boolean canRunInNewSession()
{
    return false;
}
